html:
{%- macro dt(v) -%}{{ frappe.format(v, {"fieldtype": "Date"}) if v else "" }}{%- endmacro -%}
{%- macro money(v) -%}{{ frappe.format(v, {"fieldtype": "Currency"}) if v else "" }}{%- endmacro -%}
{%- macro qty(v) -%}{{ ("%g" | format(v)) if v else "" }}{%- endmacro -%}
{%- macro text(v) -%}{{ (v or "") | e }}{%- endmacro -%}
{%- set categories = ["Design Services", "Engineering Services", "Fabrication Costs", "Materials", "Equipment", "Subcontractor Costs", "Other Costs"] -%}
{%- set lines = doc.rfd_cost_lines or [] -%}
<style>
	.rfd { font-family: Arial, Helvetica, sans-serif; color: #000; font-size: 11px; }
	.print-format .rfd td, .print-format .rfd th, .rfd td, .rfd th { padding: 3px 6px !important; vertical-align: top; line-height: 1.25; }
	.rfd table { width: 100%; border-collapse: collapse; table-layout: fixed; }
	.rfd .hdr td { vertical-align: middle; font-size: 9px; }
	.rfd h1 { font-size: 22px; font-weight: bold; text-align: center; margin: 6px 0 4px 0; padding-bottom: 3px; border-bottom: 1px solid #555; }
	.rfd .addr td { vertical-align: bottom; height: 24px; }
	.rfd .addr .lbl { font-weight: bold; width: 7%; }
	.rfd .addr .val { border-bottom: 1px solid #000; }
	.rfd .frame { border: 2px solid #000; margin-top: 8px; }
	.rfd .info td { border: 1px solid #000; height: 22px; vertical-align: middle; }
	.rfd .info .lbl { text-align: right; font-weight: bold; width: 19%; }
	.rfd .sec { font-weight: bold; }
	.rfd .text td.tb { border-bottom: 1px solid #000; height: 78px; }
	.rfd .text td.tb.last { border-bottom: none; }
	.rfd .body { margin-top: 2px; white-space: pre-wrap; }
	.rfd .cost th { border: 1px solid #000; font-weight: bold; text-align: center; background: #ececec !important; }
	.rfd .cost td { border: 1px solid #000; height: 20px; vertical-align: middle; }
	.rfd .cost .num { text-align: right; }
	.rfd .cost .tot td { font-weight: bold; }
	.rfd .nobreak { page-break-inside: avoid; }
	.rfd .foot { margin-top: 6px; font-size: 9px; page-break-inside: avoid; }
	.rfd .foot td { vertical-align: top; }
</style>
<div class="rfd">
	<table class="hdr">
		<tr>
			<td style="width:28%">355 Gus Hipp Blvd.<br>Rockledge, FL 32955</td>
			<td style="width:44%; text-align:center"><img src="{{ frappe.utils.get_url('/assets/hse/images/psif_logo.jpg') }}" style="height:52px"></td>
			<td style="width:28%; text-align:right">Tel: (321) 636-0085<br><b>www.psifla.com</b></td>
		</tr>
	</table>
	<h1>{{ _("QM-144 Request for Deviation (RFD)") }}</h1>

	<table class="addr">
		<tr>
			<td class="lbl">{{ _("To:") }}</td><td class="val" style="width:28%">{{ text(doc.rfd_to) }}</td>
			<td class="lbl" style="padding-left:14px !important">{{ _("From:") }}</td><td class="val" style="width:28%">{{ text(doc.rfd_from) }}</td>
			<td class="lbl" style="padding-left:14px !important">{{ _("Date:") }}</td><td class="val">{{ dt(doc.rfd_date) }}</td>
		</tr>
	</table>

	<table class="frame info">
		<tr>
			<td class="lbl">{{ _("Project Name:") }}</td><td>{{ text(doc.rfd_project_name or doc.project_name) }}</td>
			<td class="lbl" style="width:21%">{{ _("Project Number:") }}</td><td>{{ text(doc.rfd_project_number or doc.trulinx_work_order) }}<span style="float:right; font-size:8px; color:#555">{{ doc.name }}</span></td>
		</tr>
		<tr>
			<td class="lbl">{{ _("RFD Number:") }}</td><td>{{ text(doc.rfd_number) }}</td>
			<td class="lbl">{{ _("Date Issued:") }}</td><td>{{ dt(doc.rfd_date_issued) }}</td>
		</tr>
	</table>

	<table class="frame text">
		<tr><td class="tb"><span class="sec">{{ _("Description of Deviation") }}</span><div class="body">{{ text(doc.rfd_description) }}</div></td></tr>
		<tr><td class="tb"><span class="sec">{{ _("Reason for Deviation") }}</span><div class="body">{{ text(doc.rfd_reason) }}</div></td></tr>
		<tr><td class="tb last"><span class="sec">{{ _("Impact on Project") }}</span><div class="body">{{ text(doc.rfd_impact) }}</div></td></tr>
	</table>

	<div class="nobreak">
	<table class="frame" style="border:none">
		<tr><td style="padding:6px 0 3px 0 !important"><span class="sec">{{ _("Cost Breakdown") }}</span> {{ _("(IF NEEDED)") }}</td></tr>
	</table>
	<table class="cost">
		<tr>
			<th style="width:46%; text-align:left">{{ _("Description") }}</th>
			<th style="width:14%">{{ _("Quantity") }}</th>
			<th style="width:20%">{{ _("Unit Price") }}</th>
			<th style="width:20%">{{ _("Total") }}</th>
		</tr>
		{%- if lines %}
		{%- for r in lines %}
		<tr><td>{{ text(r.description) }}</td><td class="num">{{ qty(r.qty) }}</td><td class="num">{{ money(r.unit_price) }}</td><td class="num">{{ money(r.amount) }}</td></tr>
		{%- endfor %}
		{%- else %}
		{%- for c in categories %}
		<tr><td>{{ _(c) }}</td><td></td><td></td><td></td></tr>
		{%- endfor %}
		{%- endif %}
		<tr class="tot"><td colspan="3" class="num">{{ _("Total Change Order Cost") }}</td><td class="num">{{ money(doc.rfd_total_cost) }}</td></tr>
	</table>
	</div>

	<table class="frame text nobreak">
		<tr><td class="tb last"><span class="sec">{{ _("Payment Schedule") }}</span> {{ _("(IF NEEDED)") }}<div class="body">{{ text(doc.rfd_payment_schedule) }}</div></td></tr>
	</table>

	<table class="foot">
		<tr>
			<td style="width:30%">{% if doc.rfd_change_order %}{{ _("Change Order") }}: {{ doc.rfd_change_order }}{% endif %}</td>
			<td style="width:40%; text-align:center">{{ _("QM-144 Request for Deviation (RFD)") }}<br><i>{{ _("Printed copies of this form are uncontrolled") }}</i></td>
			<td style="width:30%; text-align:right">{{ _("Rev. 1: 10/25") }}</td>
		</tr>
	</table>
</div>
